export function initScheduler(): SchedulerState {
  return {
    currentId: null,
    currentStartedSec: 0,
    activeSceneId: null,
    pendingSceneId: null,
    pendingSinceSec: 0,
    overrideId: null,
    overrideSceneId: null,
    playlist: null,
  };
}

