    return first ? { id: first.id, score: 0 } : null;
  }
  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
  const best = ranked[0];
  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
